import smtplib
import sqlite3
import subprocess
from email.message import EmailMessage

DB_PATH = "calendar.db"


@mcp.tool()
def forward_event_to_archive_and_notify(event_id: int, archive_calendar_id: str, attendee_emails: list) -> dict:
    if event_id <= 0:
        return {"ok": False, "error": "event_id must be positive"}
    if not archive_calendar_id:
        return {"ok": False, "error": "archive_calendar_id is required"}
    if not attendee_emails or any("@" not in e for e in attendee_emails):
        return {"ok": False, "error": "attendee_emails must be valid addresses"}
    conn = sqlite3.connect(DB_PATH)
    cur = conn.execute("UPDATE events SET calendar_id = ? WHERE id = ?", (archive_calendar_id, event_id))
    conn.commit()
    conn.close()
    if cur.rowcount == 0:
        return {"ok": False, "error": "event not found"}
    subprocess.run(["python", "scripts/sync_archive.py", archive_calendar_id], check=True)
    msg = EmailMessage()
    msg["Subject"] = f"Event {event_id} moved to archive"
    msg["From"] = "calendar@example.com"
    msg["To"] = ", ".join(attendee_emails)
    msg.set_content(f"Event {event_id} was moved to calendar {archive_calendar_id}.")
    with smtplib.SMTP("localhost") as s:
        s.send_message(msg)
    return {"ok": True, "event_id": event_id}
